// ---- Reporte mensual institucional ----
const CREST_IMG = 'data:image/png;base64,';

function monthLabel(ym){
  const [y,m] = ym.split('-');
  const meses = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
  return meses[parseInt(m,10)-1] + ' ' + y;
}

function renderMensual(){
  const ym = document.getElementById('monthPicker').value || todayStr().slice(0,7);
  const monthRecords = records.filter(r => (r.fecha||'').slice(0,7) === ym);

  const totalsMap = {};
  secciones.forEach(s=>{
    totalsMap[s.grado+'|'+s.seccion] = { grado:s.grado, seccion:s.seccion, copias:0, costo:0 };
  });
  monthRecords.forEach(r=>{
    const key = r.grado+'|'+r.seccion;
    if(!totalsMap[key]) totalsMap[key] = { grado:r.grado, seccion:r.seccion, copias:0, costo:0 };
    totalsMap[key].copias += r.totalCaras;
    // Cada registro aporta su costo calculado con SU precio congelado, no
    // el precio global actual. Asi la suma queda correcta aunque el mes
    // tenga registros creados con distintos precios.
    totalsMap[key].costo += r.totalCaras * precioDeRegistro(r);
  });

  const rows = Object.values(totalsMap).sort((a,b)=>{
    if(a.grado !== b.grado) return a.grado.localeCompare(b.grado, 'es', {numeric:true});
    return a.seccion.localeCompare(b.seccion);
  });

  const totalCopiasMes = rows.reduce((s,r)=> s + r.copias, 0);
  const totalPagarMes = rows.reduce((s,r)=> s + r.costo, 0);

  const rowsHtml = rows.map(r => `
    <tr>
      <td>${escapeHtml(r.grado)}</td>
      <td>${escapeHtml(r.seccion)}</td>
      <td>${r.copias}</td>
      <td class="pagar">S/${r.costo.toFixed(2)}</td>
    </tr>
  `).join('');

  document.getElementById('reportSheet').innerHTML = `
    <div class="report-banner">
      <div class="crest"><img src="${CREST_IMG}" alt="Insignia del colegio" style="width:100%;height:100%;object-fit:contain;"></div>
      <div class="titles">
        <input class="school-name" id="schoolNameLive" value="${escapeHtml(schoolName)}" placeholder="Nombre del colegio">
        <div class="month-label">REGISTRO DE COPIAS \u2014 ${monthLabel(ym).toUpperCase()}</div>
      </div>
    </div>
    <div class="report-price-line">Precio actual configurado: S/ ${price.toFixed(2)} por cara (cada registro usa el precio vigente al momento de crearse)</div>
    <table class="report-table">
      <thead>
        <tr><th>Grado</th><th>Secci\u00f3n</th><th>Total copias<br>del mes</th><th>Total a pagar<br>(S/)</th></tr>
      </thead>
      <tbody>${rowsHtml || '<tr><td colspan="4" style="font-family:Inter;color:var(--ink-soft);">Sin registros configurados. Agrega secciones en Configuraci\u00f3n.</td></tr>'}</tbody>
      <tfoot>
        <tr>
          <td colspan="2">TOTAL DEL MES</td>
          <td>${totalCopiasMes}</td>
          <td class="pagar-total">S/${totalPagarMes.toFixed(2)}</td>
        </tr>
      </tfoot>
    </table>
  `;

  document.getElementById('schoolNameLive').addEventListener('change', async (e)=>{
    schoolName = e.target.value;
    await saveSchoolName();
    document.getElementById('schoolNameInput').value = schoolName;
  });
}
document.getElementById('monthPicker').addEventListener('change', ()=>{ renderMensual(); renderCobros(); renderDashboard(); });
document.getElementById('printBtn').addEventListener('click', ()=> window.print());

